public class Main {
    static String[] todos = new String[5];
    static int jumlah = 0;
    static boolean[] selesai = new boolean[5];

    public static void main(String[] args) {
        System.out.println("Kapasitas: " + todos.length);
        System.out.println("Terisi: " + jumlah);
        todos[0] = "Belajar Java";
        jumlah = 1;
        System.out.println("Todo pertama: " + todos[0]);
        System.out.println("Slot kosong: " + (todos.length - jumlah));
        System.out.println("Slot kedua: " + todos[1]);
        System.out.println("Status pertama: " + selesai[0]);
    }
}

